-- ADCT, comentários didáticos, lote 2 (arts. 13 a 21, inclusive 18-A), só a partir do texto no banco. Já aplicado.
update legislacao set contexto = $c$Criação do Estado do Tocantins$c$, aplicacao_pratica = $a$Criou o Estado do Tocantins, por desmembramento de área descrita no artigo, com instalação no quadragésimo sexto dia após a eleição do § 3º, mas não antes de 1º de janeiro de 1989. O § 1º fixou seus limites com Goiás, o § 2º previu capital provisória designada pelo Poder Executivo, o § 3º regulou a eleição de Governador, Vice-Governador, Senadores e Deputados em turno único, com normas sobre filiação, calendário, inelegibilidade e diretórios (I a IV), o § 4º fixou o término dos mandatos eleitos, o § 5º tratou da instalação da Assembleia Estadual Constituinte, o § 6º aplicou as normas da divisão do Estado de Mato Grosso, observado o art. 234, e o § 7º liberou Goiás dos débitos decorrentes de empreendimentos no novo Estado, autorizando a União a assumi-los. Norma transitória de aplicação já exaurida.$a$ where codigo='adct' and numero=13 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Estados de Roraima e Amapá$c$, aplicacao_pratica = $a$Transformou os Territórios Federais de Roraima e do Amapá em Estados Federados, mantidos seus limites geográficos. O § 1º vinculou a instalação à posse dos governadores eleitos em 1990, o § 2º aplicou as normas e critérios seguidos na criação do Estado de Rondônia, o § 3º determinou o envio ao Senado, em até quarenta e cinco dias da promulgação, dos nomes dos governadores que exerceriam o Executivo até a instalação e o § 4º beneficiou os Territórios, enquanto não transformados, com as transferências dos arts. 159, I, a, da Constituição e 34, § 2º, II, do Ato. Norma transitória de aplicação já exaurida.$a$ where codigo='adct' and numero=14 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Extinção do Território de Fernando de Noronha$c$, aplicacao_pratica = $a$Extinguiu o Território Federal de Fernando de Noronha e reincorporou sua área ao Estado de Pernambuco.$a$ where codigo='adct' and numero=15 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Governo do Distrito Federal na transição$c$, aplicacao_pratica = $a$Atribuiu ao Presidente da República, com aprovação do Senado Federal, indicar o Governador e o Vice-Governador do Distrito Federal até que se efetivasse o art. 32, § 2º, da Constituição. O § 1º conferiu ao Senado Federal a competência da Câmara Legislativa até sua instalação, o § 2º atribuiu ao Senado, com o auxílio do Tribunal de Contas do Distrito Federal, a fiscalização contábil, financeira, orçamentária, operacional e patrimonial do Distrito Federal nesse período, observado o art. 72, e o § 3º incluiu entre os bens do Distrito Federal os que lhe fossem atribuídos pela União na forma da lei. Norma transitória de aplicação já exaurida.$a$ where codigo='adct' and numero=16 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Redução de vencimentos em desacordo com a Constituição$c$, aplicacao_pratica = $a$Determinou a imediata redução aos limites constitucionais dos vencimentos, remuneração, vantagens, adicionais e proventos de aposentadoria percebidos em desacordo com a Constituição, sem admitir invocação de direito adquirido ou percepção de excesso a qualquer título. O § 1º assegurou o exercício cumulativo de dois cargos ou empregos privativos de médico por médico militar e o § 2º o exercício cumulativo de dois cargos ou empregos privativos de profissionais de saúde que já estivessem sendo exercidos na administração pública direta ou indireta.$a$ where codigo='adct' and numero=17 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Estabilidade concedida sem concurso após a Constituinte$c$, aplicacao_pratica = $a$Extinguiu os efeitos jurídicos de qualquer ato legislativo ou administrativo, lavrado a partir da instalação da Assembleia Nacional Constituinte, que tenha por objeto a concessão de estabilidade a servidor admitido sem concurso público, da administração direta ou indireta, inclusive das fundações instituídas e mantidas pelo Poder Público.$a$ where codigo='adct' and numero=18 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Convalidação de atos do Estado do Tocantins$c$, aplicacao_pratica = $a$Convalida, após cinco anos contados da data em que foram praticados, os atos administrativos do Estado do Tocantins decorrentes de sua instalação, entre 1º de janeiro de 1989 e 31 de dezembro de 1994, eivados de qualquer vício jurídico e dos quais decorram efeitos favoráveis aos destinatários, salvo comprovada má-fé.$a$ where codigo='adct' and numero=18 and titulo='Art. 18-A' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Estabilidade de servidores sem concurso$c$, aplicacao_pratica = $a$Considera estáveis no serviço público os servidores civis da União, dos Estados, do Distrito Federal e dos Municípios, da administração direta, autárquica e das fundações públicas, em exercício na data da promulgação há pelo menos cinco anos continuados e não admitidos na forma do art. 37. O § 1º conta o tempo de serviço como título em concurso para efetivação, o § 2º exclui os ocupantes de cargos, funções e empregos de confiança ou em comissão e os de livre exoneração, e o § 3º exclui os professores de nível superior, nos termos da lei.$a$ where codigo='adct' and numero=19 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Revisão de proventos e pensões$c$, aplicacao_pratica = $a$Determinou que, em cento e oitenta dias, se procedesse à revisão dos direitos dos servidores públicos inativos e pensionistas e à atualização dos proventos e pensões, para ajustá-los ao disposto na Constituição. Norma transitória de aplicação já exaurida.$a$ where codigo='adct' and numero=20 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Juízes togados de investidura temporária$c$, aplicacao_pratica = $a$Conferiu estabilidade, observado o estágio probatório, aos juízes togados de investidura limitada no tempo, admitidos por concurso público de provas e títulos e em exercício na data da promulgação, que passaram a compor quadro em extinção, mantidas as competências, prerrogativas e restrições da legislação anterior, salvo as inerentes à transitoriedade da investidura. O parágrafo único submete sua aposentadoria às normas fixadas para os demais juízes estaduais.$a$ where codigo='adct' and numero=21 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
